40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    private String address;
48	
49	    @Column(name = "address_line1")
50	    private String addressLine1;
51	
52	    @Column(name = "address_line2")
53	    private String addressLine2;
54	
55	    @Column(name = "city")
56	    @NotEmpty
57	    private String city;
58	
59	    @Column(name = "postcode")
60	    private String postcode;
61	
62	    @Column(name = "telephone")
63	    @NotEmpty
64	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
65	    private String telephone;
66	
67	    @Column(name = "email")
68	    @Email
69	    private String email;
70	
71	    @Column(name = "registration_date", columnDefinition = "DATE")
72	    private LocalDate registrationDate;
73	
74	    @Column(name = "birth_date", columnDefinition = "DATE")
75	    private LocalDate birthDate;
