77	    @Column(name = "customer_code")
78	    private String customerCode;
79	
80	    @Column(name = "membership_number")
81	    private String membershipNumber;
82	
83	    @Column(name = "household_id")
84	    private String householdId;
85	
86	    @Column(name = "namesake_count")
87	    private Integer namesakeCount;
88	
89	    @Column(name = "bulk_signup_warning")
90	    private boolean bulkSignupWarning;
91	
92	    @Column(name = "capacity_warning")
93	    private boolean capacityWarning;
94	
95	    @Column(name = "household_member_count")
96	    private Integer householdMemberCount;
97	
98	    @Column(name = "membership_level_cap")
99	    private Integer membershipLevelCap;
100	
101	    @Column(name = "possible_duplicate")
102	    private boolean possibleDuplicate;
103	
104	    @Column(name = "possible_duplicate_of")
105	    private Integer possibleDuplicateOf;
106	
107	    @Column(name = "deleted")
108	    private boolean deleted;
109	
