124	    /**
125	     * Derive the owner's read-only {@code salutation}: the honorific {@code title} and
126	     * {@code lastName} joined by a single space ({@code '<title> <lastName>'}) when a title has
127	     * been supplied, otherwise just the {@code lastName}. A {@code null} or blank title yields the
128	     * bare last name.
129	     */
130	    @Transient
131	    public String getSalutation() {
132	        if (this.title == null || this.title.isBlank()) {
133	            return getLastName();
134	        }
135	        return this.title + " " + getLastName();
136	    }
