170	    public String getPostcode() {
171	        return this.postcode;
172	    }
173	
174	    public void setPostcode(String postcode) {
175	        this.postcode = postcode;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    public void setTelephone(String telephone) {
183	        this.telephone = telephone;
184	    }
