186	    public String getEmail() {
187	        return this.email;
188	    }
189	
190	    public void setEmail(String email) {
191	        this.email = email;
192	    }
193	
194	    public LocalDate getRegistrationDate() {
195	        return this.registrationDate;
196	    }
197	
198	    public void setRegistrationDate(LocalDate registrationDate) {
199	        this.registrationDate = registrationDate;
200	    }
201	
202	    public LocalDate getBirthDate() {
203	        return this.birthDate;
204	    }
205	
206	    public void setBirthDate(LocalDate birthDate) {
207	        this.birthDate = birthDate;
208	    }
209	
210	    /**
211	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
212	     * owner's {@code registrationDate} (falling back to the current date when no registration date
213	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
214	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
215	     */
216	    @Transient
217	    public String getAgeBand() {
218	        if (this.birthDate == null) {
219	            return null;
220	        }
221	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
222	        int age = Period.between(this.birthDate, reference).getYears();
223	        if (age < 18) {
224	            return "MINOR";
225	        }
226	        if (age < 65) {
227	            return "ADULT";
228	        }
229	        return "SENIOR";
230	    }
231	
232	    public String getCustomerCode() {
233	        return this.customerCode;
234	    }
235	
236	    public void setCustomerCode(String customerCode) {
237	        this.customerCode = customerCode;
238	    }
239	
240	    public String getMembershipNumber() {
241	        return this.membershipNumber;
242	    }
243	
244	    public void setMembershipNumber(String membershipNumber) {
245	        this.membershipNumber = membershipNumber;
246	    }
247	
248	    public String getHouseholdId() {
249	        return this.householdId;
250	    }
251	
252	    public void setHouseholdId(String householdId) {
253	        this.householdId = householdId;
254	    }
255	
256	    public Integer getNamesakeCount() {
257	        return this.namesakeCount;
258	    }
259	
260	    public void setNamesakeCount(Integer namesakeCount) {
261	        this.namesakeCount = namesakeCount;
262	    }
263	
264	    /**
265	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
266	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
267	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
268	     * the owner's tenure is at least one elapsed fiscal year (measured from the
269	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
270	     */
271	    @Transient
272	    public Integer getMembershipPoints() {
273	        int points = 0;
274	        if (this.email != null && !this.email.isBlank()) {
275	            points += 2;
276	        }
277	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
278	            points += 1;
279	        }
280	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
281	            points += 2;
282	        }
283	        if (hasTenureOverOneFiscalYear()) {
284	            points += 3;
285	        }
286	        return points;
287	    }
288	
289	    /**
290	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
291	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
292	     * points, and level 4 for 6 or more points. The result is then capped at the owner's
293	     * {@code membershipLevelCap} when one has been assigned, so a new household member can never
294	     * exceed one above the highest level already present in their household (see
295	     * {@link #getMembershipLevelCap()}).
296	     */
297	    @Transient
298	    public Integer getMembershipLevel() {
299	        int points = getMembershipPoints();
300	        int level;
301	        if (points <= 1) {
302	            level = 1;
303	        }
304	        else if (points <= 3) {
305	            level = 2;
306	        }
307	        else if (points <= 5) {
308	            level = 3;
309	        }
310	        else {
311	            level = 4;
312	        }
313	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
314	            return this.membershipLevelCap;
315	        }
316	        return level;
317	    }
318	
319	    /**
320	     * The ceiling applied to this owner's derived {@code membershipLevel}: one above the highest
321	     * {@code membershipLevel} among the owner's household members (same last name and postcode) at
322	     * creation time. {@code null} when the owner had no existing household member, in which case no
323	     * cap applies.
324	     */
325	    public Integer getMembershipLevelCap() {
326	        return this.membershipLevelCap;
327	    }
328	
329	    public void setMembershipLevelCap(Integer membershipLevelCap) {
330	        this.membershipLevelCap = membershipLevelCap;
331	    }
332	
333	    /**
334	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
335	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
336	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
337	     * never qualifies.
338	     */
339	    @Transient
340	    private boolean hasTenureOverOneFiscalYear() {
341	        if (this.registrationDate == null) {
342	            return false;
343	        }
344	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
345	    }
346	
347	    /**
348	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
349	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate}. The
350	     * fiscal year starts on 1 July, so a registration on or after 1 July belongs to the fiscal year
351	     * ending the following 30 June. Returns {@code null} when no {@code registrationDate} has been
352	     * assigned yet, so the field is omitted from the response.
353	     */
354	    @Transient
355	    public String getFiscalYear() {
356	        if (this.registrationDate == null) {
357	            return null;
358	        }
359	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
360	    }
361	
362	    /**
363	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
364	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
365	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
366	     * current year's fiscal year.
367	     */
368	    public static int fiscalYearOf(LocalDate date) {
369	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
370	    }
371	
372	    /**
373	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
374	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
375	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
376	     * has been assigned yet.
377	     */
378	    @Transient
379	    public Integer getCheckDigit() {
380	        if (this.customerCode == null) {
381	            return null;
382	        }
383	        int sum = 0;
384	        boolean dbl = true;
385	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
386	            char c = this.customerCode.charAt(i);
387	            if (c < '0' || c > '9') {
388	                continue;
389	            }
390	            int d = c - '0';
391	            if (dbl) {
392	                d *= 2;
393	                if (d > 9) {
394	                    d -= 9;
395	                }
396	            }
397	            sum += d;
398	            dbl = !dbl;
399	        }
400	        return (10 - (sum % 10)) % 10;
401	    }
402	
403	    /**
404	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners: the
405	     * full lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
406	     * soundex(lastName)}. The telephone and email are already stored in their canonical (E.164 /
407	     * lower-cased) form, so a {@code null} or blank email contributes an empty middle segment, and
408	     * the last name is reduced to its {@link Soundex} code (empty when there is no last name). Two
409	     * owners are duplicates only when their whole {@code identityKey} is equal.
410	     */
411	    @Transient
412	    public String getIdentityKey() {
413	        String telephonePart = this.telephone == null ? "" : this.telephone;
414	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
415	        String soundexPart = Soundex.encode(getLastName());
416	        return Sha256.hex(telephonePart + "|" + emailPart + "|" + soundexPart);
417	    }
418	
