441	        return this.householdMemberCount;
442	    }
443	
444	    public void setHouseholdMemberCount(Integer householdMemberCount) {
445	        this.householdMemberCount = householdMemberCount;
446	    }
447	
448	    /**
449	     * Whether this owner was flagged at creation as a possible (soft) duplicate: its
450	     * {@code identityKey} differs from every existing owner's, but it shares an existing owner's
451	     * {@code soundex(lastName)} and postcode. The owner is still created; this flag is advisory.
452	     */
453	    public boolean isPossibleDuplicate() {
454	        return this.possibleDuplicate;
455	    }
456	
457	    public void setPossibleDuplicate(boolean possibleDuplicate) {
458	        this.possibleDuplicate = possibleDuplicate;
459	    }
460	
461	    /**
462	     * The id of the existing owner this one soft-matched against (same {@code soundex(lastName)} and
463	     * postcode, different {@code identityKey}), or {@code null} when {@link #isPossibleDuplicate()}
464	     * is {@code false}.
465	     */
466	    public Integer getPossibleDuplicateOf() {
467	        return this.possibleDuplicateOf;
468	    }
469	
470	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
471	        this.possibleDuplicateOf = possibleDuplicateOf;
472	    }
473	
474	    /**
475	     * Whether this owner has been soft-deleted: DELETE /api/owners/{id} sets this flag rather than
476	     * removing the row, so the owner is retained and still readable but is ignored by the create
477	     * endpoint's duplicate and identity checks. A newly created owner is not deleted.
478	     */
479	    public boolean isDeleted() {
480	        return this.deleted;
481	    }
482	
483	    public void setDeleted(boolean deleted) {
484	        this.deleted = deleted;
485	    }
486	
487	    /**
488	     * The {@code Idempotency-Key} the owner was first created under, or {@code null} when the create
489	     * carried no such header. When a create repeats with an already-seen key, the originally created
490	     * owner is returned instead of a duplicate being created, so the key is retained to recognise the
491	     * repeat.
492	     */
493	    public String getIdempotencyKey() {
494	        return this.idempotencyKey;
495	    }
496	
497	    public void setIdempotencyKey(String idempotencyKey) {
498	        this.idempotencyKey = idempotencyKey;
499	    }
500	
501	    protected Set<Pet> getPetsInternal() {
502	        if (this.pets == null) {
503	            this.pets = new HashSet<>();
504	        }
505	        return this.pets;
506	    }
507	
508	    protected void setPetsInternal(Set<Pet> pets) {
509	        this.pets = pets;
510	    }
511	
512	    public List<Pet> getPets() {
513	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
514	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
515	        return Collections.unmodifiableList(sortedPets);
516	    }
