16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Renders SHA-256 digests as hex. The single home for the {@code MessageDigest} acquisition and the
24	 * "SHA-256 not available" error, shared by every derived identifier built from a SHA-256 hash (e.g.
25	 * the owner's {@code identityKey}, {@code householdId} and customer-code hash), so the digest
26	 * handling and that error live in one place.
27	 */
28	public final class Sha256 {
29	
30	    private Sha256() {
31	    }
32	
33	    /**
34	     * Compute the full lower-case hex SHA-256 over the UTF-8 bytes of {@code input} (64 hex
35	     * characters).
36	     */
37	    public static String hex(String input) {
38	        return hexPrefix(input, 32, false);
39	    }
40	
41	    /**
42	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
43	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
44	     * {@code upperCase} is {@code true}, otherwise lower-case.
45	     */
46	    public static String hexPrefix(String input, int bytes, boolean upperCase) {
47	        byte[] digest;
48	        try {
49	            digest = MessageDigest.getInstance("SHA-256")
50	                .digest(input.getBytes(StandardCharsets.UTF_8));
51	        }
52	        catch (NoSuchAlgorithmException e) {
53	            throw new IllegalStateException("SHA-256 is required but not available", e);
54	        }
55	        String format = upperCase ? "%02X" : "%02x";
56	        StringBuilder hex = new StringBuilder(bytes * 2);
57	        for (int i = 0; i < bytes; i++) {
58	            hex.append(String.format(format, digest[i]));
59	        }
60	        return hex.toString();
61	    }
62	}
