271	    @Override
272	    @Transactional
273	    public void saveOwner(Owner owner) throws DataAccessException {
274	        boolean isNew = owner.isNew();
275	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
276	        // roll it forward to the next business day so it never lands on a weekend. Everything
277	        // derived from the registration date below must use this adjusted value.
278	        LocalDate registrationDate = toBusinessDay(
279	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
280	        owner.setRegistrationDate(registrationDate);
281	        if (owner.isNew()) {
282	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
283	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
284	            // it automatically. It no longer feeds the identityKey, but is still reported and drives
285	            // the household member count and level cap below.
286	            owner.setHouseholdId(computeHouseholdId(owner));
287	            // The household is keyed on (last name, postcode), so the members are the existing owners
288	            // sharing both with this owner.
289	            List<Owner> householdMembers = findHouseholdMembers(owner);
290	            // Size of the household after this create: the existing members plus this new owner.
291	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
292	            // A new owner joining an existing household has its derived membershipLevel capped at one
293	            // above the current maximum membershipLevel among its household members, so a new member
294	            // can never leap more than one level past the household. With no existing member no cap
295	            // applies.
296	            if (!householdMembers.isEmpty()) {
297	                int maxLevel = householdMembers.stream()
298	                    .mapToInt(Owner::getMembershipLevel)
299	                    .max()
300	                    .getAsInt();
301	                owner.setMembershipLevelCap(maxLevel + 1);
302	            }
303	        }
304	        // Single duplicate check: reject only when the new owner's WHOLE identityKey (the SHA-256 of
305	        // normalizedTelephone | email-or-empty | soundex(lastName)) equals an existing owner's. This
306	        // is the only 409; there is no separate household-duplicate rejection.
307	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
308	            throw new DuplicateIdentityException(owner.getIdentityKey());
309	        }
310	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's
311	        // soundex(lastName) and postcode. Still created, but flagged as a possible duplicate pointing
312	        // at the matching owner. Because the telephone is part of the identityKey, two owners with the
313	        // same last name and postcode but different telephones are flagged here rather than rejected.
314	        if (owner.isNew()) {
315	            Owner softMatch = findPossibleDuplicate(owner);
316	            if (softMatch != null) {
317	                owner.setPossibleDuplicate(true);
318	                owner.setPossibleDuplicateOf(softMatch.getId());
319	            }
320	        }
321	        if (owner.isNew()) {
322	            long ownersInCity = countOwnersInCity(owner);
323	            if (ownersInCity >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
324	                throw new CityOwnerLimitExceededException(owner.getCity());
325	            }
326	            // Between 40 and 49 existing owners (inclusive): created, but flagged as approaching the
327	            // per-city capacity limit of 50.
328	            owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
329	        }
330	        if (owner.isNew()
331	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
332	            throw new DailyOwnerLimitExceededException(registrationDate);
333	        }
334	        if (owner.isNew() && owner.getCustomerCode() == null) {
335	            owner.setCustomerCode(generateCustomerCode(owner));
336	        }
337	        if (owner.isNew()) {
338	            owner.setNamesakeCount(countNamesakes(owner));
339	            owner.setBulkSignupWarning(
340	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
341	        }
342	        if (owner.getMembershipNumber() == null) {
343	            owner.setMembershipNumber(generateMembershipNumber(owner));
344	        }
345	        ownerRepository.save(owner);
346	        if (isNew) {
347	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
348	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
349	                owner.getMembershipNumber(), owner.getRegistrationDate());
350	            AUDIT.info(ownerCreatedEvent(owner));
351	        }
352	    }
