16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Computes the American <a href="https://en.wikipedia.org/wiki/Soundex">Soundex</a> code of a name:
20	 * its first letter followed by three digits that phonetically encode the remaining consonants, so
21	 * similarly-sounding surnames (e.g. {@code 'Smith'} and {@code 'Smyth'}) share a code.
22	 *
23	 * <p>The algorithm: keep only letters and upper-case them; retain the first letter; map each
24	 * subsequent letter to a digit ({@code B,F,P,V->1}; {@code C,G,J,K,Q,S,X,Z->2}; {@code D,T->3};
25	 * {@code L->4}; {@code M,N->5}; {@code R->6}; vowels {@code A,E,I,O,U,Y->0}); drop a digit equal to
26	 * the previous letter's digit (letters separated by {@code H} or {@code W} count as adjacent, so
27	 * their shared digit collapses, but letters separated by a vowel are coded twice); drop the vowel
28	 * zeros; then truncate or zero-pad to exactly four characters. A value with no letters yields the
29	 * empty string.
30	 */
31	public final class Soundex {
32	
33	    /** Digit for each letter A-Z; {@code '0'} marks a vowel (A, E, I, O, U, Y) that resets runs. */
34	    private static final String MAPPING = "01230120022455012623010202";
35	
36	    private Soundex() {
37	    }
38	
39	    /**
40	     * Encode {@code value} as its four-character Soundex code, or the empty string when the value is
41	     * {@code null} or contains no letters.
42	     */
43	    public static String encode(String value) {
44	        if (value == null) {
45	            return "";
46	        }
47	        StringBuilder letters = new StringBuilder();
48	        for (int i = 0; i < value.length(); i++) {
49	            char c = value.charAt(i);
50	            if (Character.isLetter(c)) {
51	                letters.append(Character.toUpperCase(c));
52	            }
53	        }
54	        if (letters.length() == 0) {
55	            return "";
56	        }
57	        StringBuilder code = new StringBuilder();
58	        char first = letters.charAt(0);
59	        code.append(first);
60	        char last = codeOf(first);
61	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
62	            char c = letters.charAt(i);
63	            if (c == 'H' || c == 'W') {
64	                // Transparent: does not reset the previous digit, so letters it separates collapse.
65	                continue;
66	            }
67	            char digit = codeOf(c);
68	            if (digit != '0' && digit != last) {
69	                code.append(digit);
70	            }
71	            last = digit;
72	        }
73	        while (code.length() < 4) {
74	            code.append('0');
75	        }
76	        return code.toString();
77	    }
78	
79	    /** The Soundex digit for an upper-case letter A-Z. */
80	    private static char codeOf(char letter) {
81	        return MAPPING.charAt(letter - 'A');
82	    }
83	}
