154	
155	    /**
156	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
157	     *
158	     * @param e The {@link Exception} to be handled
159	     * @param request {@link HttpServletRequest} object referring to the current request.
160	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
161	     */
162	    @ExceptionHandler(Exception.class)
163	    @ResponseBody
164	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
165	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
166	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
167	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
173	     * method returns a 404 Not Found status if an entity does not exist.
174	     *
175	     * @param e The {@link DataIntegrityViolationException} to be handled
176	     * @param request {@link HttpServletRequest} object referring to the current request.
177	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
178	     */
179	    @ExceptionHandler(DataIntegrityViolationException.class)
180	    @ResponseBody
181	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
182	        logger.warn("Data integrity violation at {} {}: {}",
183	            request.getMethod(),
184	            request.getRequestURI(),
185	            e.getMessage());
186	        logger.debug("Data integrity violation stacktrace", e);
187	        HttpStatus status = HttpStatus.NOT_FOUND;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	    /**
193	     * Handles exception thrown by Bean Validation on controller methods parameters. The response
194	     * body carries an {@code errors} array naming each rejected field (e.g. a required field that
195	     * is missing or blank), alongside the detailed {@code schemaValidationErrors}.
196	     *
197	     * @param e The {@link MethodArgumentNotValidException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(MethodArgumentNotValidException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
204	        HttpStatus status = HttpStatus.BAD_REQUEST;
205	        BindingErrorsResponse errors = new BindingErrorsResponse();
206	        BindingResult bindingResult = e.getBindingResult();
207	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
208	        if (bindingResult.hasErrors()) {
209	            errors.addAllErrors(bindingResult);
210	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
211	                .map(FieldError::getField)
212	                .distinct()
213	                .toList();
214	            detail.setProperty("errors", invalidFields);
215	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
216	                .map(fieldError -> {
217	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
218	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
219	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
220	                        fieldError.getField(),
221	                        defaultMessage,
222	                        rejectedValue);
223	                    return new ValidationMessageDto(message)
224	                        .putAdditionalProperty("field", fieldError.getField())
225	                        .putAdditionalProperty("rejectedValue", rejectedValue)
226	                        .putAdditionalProperty("defaultMessage", defaultMessage);
227	                })
228	                .toList();
229	            logger.debug("Validation error at {} {}: {}",
230	                request.getMethod(),
231	                request.getRequestURI(),
232	                bindingResult.getFieldErrors());
233	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
234	            return ResponseEntity.status(status).body(detail);
235	        }
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	}
