159	        this.addressLine2 = addressLine2;
160	    }
161	
162	    public String getCity() {
163	        return this.city;
164	    }
165	
166	    public void setCity(String city) {
167	        this.city = city;
168	    }
169	
170	    public String getPostcode() {
171	        return this.postcode;
172	    }
173	
174	    public void setPostcode(String postcode) {
175	        this.postcode = postcode;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    public void setTelephone(String telephone) {
183	        this.telephone = telephone;
184	    }
185	
186	    public String getEmail() {
187	        return this.email;
188	    }
189	
190	    public void setEmail(String email) {
191	        this.email = email;
192	    }
193	
194	    public LocalDate getRegistrationDate() {
195	        return this.registrationDate;
196	    }
197	
