271	    @Override
272	    @Transactional
273	    public void saveOwner(Owner owner) throws DataAccessException {
274	        boolean isNew = owner.isNew();
275	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
276	        // roll it forward to the next business day so it never lands on a weekend. Everything
277	        // derived from the registration date below must use this adjusted value.
278	        LocalDate registrationDate = toBusinessDay(
279	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
280	        owner.setRegistrationDate(registrationDate);
281	        if (owner.isNew()) {
282	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
283	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
284	            // it automatically. It no longer feeds the identityKey, but is still reported and drives
285	            // the household member count and level cap below.
286	            owner.setHouseholdId(computeHouseholdId(owner));
287	            // The household is keyed on (last name, postcode), so the members are the existing owners
288	            // sharing both with this owner.
289	            List<Owner> householdMembers = findHouseholdMembers(owner);
290	            // Size of the household after this create: the existing members plus this new owner.
291	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
292	            // A new owner joining an existing household has its derived membershipLevel capped at one
293	            // above the current maximum membershipLevel among its household members, so a new member
294	            // can never leap more than one level past the household. With no existing member no cap
295	            // applies.
296	            if (!householdMembers.isEmpty()) {
297	                int maxLevel = householdMembers.stream()
298	                    .mapToInt(Owner::getMembershipLevel)
299	                    .max()
300	                    .getAsInt();
301	                owner.setMembershipLevelCap(maxLevel + 1);
302	            }
303	        }
304	        // Single duplicate check: reject only when the new owner's WHOLE identityKey (the SHA-256 of
305	        // normalizedTelephone | email-or-empty | soundex(lastName)) equals an existing owner's. This
306	        // is the only 409; there is no separate household-duplicate rejection.
307	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
308	            throw new DuplicateIdentityException(owner.getIdentityKey());
309	        }
310	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's
311	        // soundex(lastName) and postcode. Still created, but flagged as a possible duplicate pointing
312	        // at the matching owner. Because the telephone is part of the identityKey, two owners with the
313	        // same last name and postcode but different telephones are flagged here rather than rejected.
314	        if (owner.isNew()) {
315	            Owner softMatch = findPossibleDuplicate(owner);
316	            if (softMatch != null) {
317	                owner.setPossibleDuplicate(true);
318	                owner.setPossibleDuplicateOf(softMatch.getId());
319	            }
320	        }
321	        if (owner.isNew()) {
322	            long ownersInCity = countOwnersInCity(owner);
323	            if (ownersInCity >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
324	                throw new CityOwnerLimitExceededException(owner.getCity());
325	            }
326	            // Between 40 and 49 existing owners (inclusive): created, but flagged as approaching the
327	            // per-city capacity limit of 50.
328	            owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
329	        }
330	        if (owner.isNew()
331	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
332	            throw new DailyOwnerLimitExceededException(registrationDate);
333	        }
334	        if (owner.isNew() && owner.getCustomerCode() == null) {
335	            owner.setCustomerCode(generateCustomerCode(owner));
336	        }
337	        if (owner.isNew()) {
338	            owner.setNamesakeCount(countNamesakes(owner));
339	            owner.setBulkSignupWarning(
340	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
341	        }
342	        if (owner.getMembershipNumber() == null) {
343	            owner.setMembershipNumber(generateMembershipNumber(owner));
344	        }
345	        ownerRepository.save(owner);
346	        if (isNew) {
347	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
348	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
349	                owner.getMembershipNumber(), owner.getRegistrationDate());
350	            AUDIT.info(ownerCreatedEvent(owner));
351	        }
352	    }
353	
354	    /**
355	     * Build the immutable structured owner-created event emitted alongside the human-readable audit
356	     * line and serialize it to JSON. {@code seq} is a process-wide monotonically increasing integer
357	     * stamped once per create, so the ordering of creates is recoverable from the audit stream.
358	     *
359	     * <p>The event carries the owner's <em>current primary identifier</em> under the
360	     * {@code customerCode} field (see {@link #primaryIdentifier(Owner)}); when the customerCode is
361	     * later unified into the memberId, that single method changes and the event automatically carries
362	     * the memberId instead.
363	     */
364	    private String ownerCreatedEvent(Owner owner) {
365	        OwnerCreatedEvent event = new OwnerCreatedEvent(
366	            OWNER_CREATED_SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner),
367	            owner.getMembershipLevel(), "OWNER_CREATED");
368	        return AUDIT_MAPPER.writeValueAsString(event);
369	    }
370	
371	    /**
372	     * The owner's current primary identifier carried by audit events. Today this is the
373	     * {@code customerCode}; the single source of truth lives here so that when the customerCode is
374	     * unified into the memberId, only this method changes and every emitted event follows.
375	     */
376	    private String primaryIdentifier(Owner owner) {
377	        return owner.getCustomerCode();
378	    }
379	
380	    /**
381	     * Immutable structured owner-created audit event. Serialized to the JSON object
382	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}; the
383	     * {@code customerCode} field carries the owner's current primary identifier.
384	     */
385	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
386	        Integer membershipLevel, String event) {
387	    }
388	
389	    /**
390	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
391	     * (non-deleted) owner. The key is the SHA-256 of telephone, email and {@code soundex(lastName)}
392	     * combined, so two owners collide only when their whole key is equal (see
393	     * {@link Owner#getIdentityKey()}).
394	     */
395	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
396	        String identityKey = owner.getIdentityKey();
397	        return ownerRepository.findAll().stream()
398	            .filter(existing -> !existing.isDeleted())
399	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
400	    }
401	
402	    /**
403	     * Find an existing owner this (new) owner soft-matches against: one sharing the same
404	     * {@code soundex(lastName)} and postcode, but carrying a different {@code identityKey}. Returns
405	     * the lowest-id such owner, or {@code null} when the owner has no last name or postcode to match
406	     * on, or nothing matches. The caller only invokes this once the hard {@code identityKey}
407	     * duplicate check has already passed.
408	     */
409	    private Owner findPossibleDuplicate(Owner owner) {
410	        String key = soundexPostcodeKey(owner);
411	        if (key == null) {
412	            return null;
413	        }
414	        String identityKey = owner.getIdentityKey();
415	        return ownerRepository.findAll().stream()
416	            .filter(existing -> !existing.isDeleted())
417	            .filter(existing -> key.equals(soundexPostcodeKey(existing))
418	                && !identityKey.equals(existing.getIdentityKey()))
419	            .min(Comparator.comparing(Owner::getId))
420	            .orElse(null);
421	    }
422	
423	    /**
424	     * Build the soft-match key, {@code soundex(lastName) + '|' + postcode}: the basis on which a new
425	     * owner is flagged a possible duplicate of an existing owner. Returns {@code null} when the owner
426	     * has no last name to encode or no postcode to key on.
427	     */
428	    private String soundexPostcodeKey(Owner owner) {
429	        String soundex = Soundex.encode(owner.getLastName());
430	        String postcode = owner.getPostcode();
431	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
432	            return null;
433	        }
434	        return soundex + "|" + postcode;
435	    }
436	
437	    /**
438	     * Count the owners that already exist (before this create) sharing the same first name and last
439	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
440	     * unique among the existing owners.
441	     */
442	    private int countNamesakes(Owner owner) {
443	        String firstName = owner.getFirstName();
444	        String lastName = owner.getLastName();
445	        if (firstName == null || lastName == null) {
446	            return 0;
447	        }
448	        return (int) ownerRepository.findAll().stream()
449	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
450	                && lastName.equalsIgnoreCase(existing.getLastName()))
451	            .count();
452	    }
453	
454	    /**
455	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
456	     * last name and its postcode. Last names are compared case-insensitively with collapsed
457	     * whitespace; postcodes are compared exactly. This is the same keying used by
458	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
459	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
460	     * postcode to match on.
461	     */
462	    private List<Owner> findHouseholdMembers(Owner owner) {
463	        String key = householdKey(owner);
464	        if (key == null) {
465	            return List.of();
466	        }
467	        return ownerRepository.findAll().stream()
468	            .filter(existing -> !existing.isDeleted())
469	            .filter(existing -> key.equals(householdKey(existing)))
470	            .toList();
471	    }
472	
473	    /**
474	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
475	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
476	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
477	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
478	     * postcode, so it does not belong to a shared household.
479	     */
480	    private String computeHouseholdId(Owner owner) {
481	        String key = householdKey(owner);
482	        return key == null ? null : Sha256.hexPrefix(key, 6, false);
483	    }
484	
485	    /**
486	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
487	     * that identifies a household. The last name is normalized case-insensitively with collapsed
488	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
489	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
490	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
491	     * cannot drift apart.
492	     */
493	    private String householdKey(Owner owner) {
494	        String lastName = normalizeHouseholdKey(owner.getLastName());
495	        String postcode = owner.getPostcode();
496	        if (lastName == null || postcode == null || postcode.isBlank()) {
497	            return null;
498	        }
499	        return lastName + "|" + postcode;
500	    }
501	
502	    /**
503	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
504	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
505	     */
506	    private String normalizeHouseholdKey(String value) {
507	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
508	    }
509	
510	    /**
511	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
512	     * code resolved from the owner's postcode (falling back to the owner's city, else
513	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
514	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
515	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
516	     * derived from the owner's own attributes.
517	     * <p>
518	     * When the derived code collides with an existing owner's {@code customerCode}, a
519	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes it
520	     * unique, so distinct owners always receive distinct customer codes.
521	     */
522	    private String generateCustomerCode(Owner owner) {
523	        String base = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
524	        return deduplicateCustomerCode(base);
525	    }
526	
527	    /**
528	     * Return {@code base} when no existing owner already uses it as their {@code customerCode};
529	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
530	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
531	     */
532	    private String deduplicateCustomerCode(String base) {
533	        Set<String> existing = ownerRepository.findAll().stream()
534	            .map(Owner::getCustomerCode)
535	            .filter(Objects::nonNull)
536	            .collect(Collectors.toSet());
537	        if (!existing.contains(base)) {
538	            return base;
539	        }
540	        int n = 2;
541	        while (existing.contains(base + "-" + n)) {
542	            n++;
543	        }
544	        return base + "-" + n;
545	    }
546	
547	    /**
548	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
549	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
550	     * with the owner's last name.
551	     */
552	    private String customerHash(Owner owner) {
553	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
554	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
555	        return Sha256.hexPrefix(telephone + lastName, 4, true);
556	    }
557	
558	    /**
559	     * Count the owners that already exist (before this create) in the same city as {@code owner},
560	     * compared case-insensitively.
561	     */
562	    private long countOwnersInCity(Owner owner) {
563	        String city = owner.getCity();
564	        return ownerRepository.findAll().stream()
565	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
566	            .count();
567	    }
568	
569	    /**
570	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
571	     * on the given {@code date}. Used to enforce the per-day create cap.
572	     */
573	    private long countOwnersRegisteredOn(LocalDate date) {
574	        return ownerRepository.findAll().stream()
575	            .filter(existing -> date.equals(existing.getRegistrationDate()))
576	            .count();
577	    }
578	
579	    /**
580	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
581	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
582	     */
583	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
584	        LocalDate.parse("2026-01-01"),
585	        LocalDate.parse("2026-01-26"),
586	        LocalDate.parse("2026-04-25"),
587	        LocalDate.parse("2026-12-25"),
588	        LocalDate.parse("2026-12-28"));
589	
590	    /**
591	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
592	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
593	     * unchanged. Registration dates are required to fall on a business day.
594	     */
595	    private LocalDate toBusinessDay(LocalDate date) {
596	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
597	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
598	            || PUBLIC_HOLIDAYS.contains(date)) {
599	            date = date.plusDays(1);
600	        }
601	        return date;
602	    }
603	
604	    /**
605	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
606	     * last two digits of the fiscal year of the owner's business-day-adjusted
607	     * {@code registrationDate} (the fiscal year starting 1 July), e.g. {@code 'NSW-1A2B3C4D-M27'}.
608	     */
609	    private String generateMembershipNumber(Owner owner) {
610	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
611	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
612	    }
613	
614	    @Override
615	    @Transactional(readOnly = true)
616	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
617	        return ownerRepository.findByLastName(lastName);
618	    }
619	
620	    /**
621	     * Find the owner originally created under the given {@code Idempotency-Key}, or {@code null} when
622	     * the key is blank or no (non-deleted) owner carries it. Used by the create endpoint to recognise
623	     * a repeated create and return the first-created owner instead of creating a duplicate.
624	     */
625	    @Override
626	    @Transactional(readOnly = true)
627	    public Owner findOwnerByIdempotencyKey(String idempotencyKey) throws DataAccessException {
628	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
629	            return null;
630	        }
631	        return ownerRepository.findByIdempotencyKey(idempotencyKey);
632	    }
633	
634	    @Override
635	    @Transactional(readOnly = true)
636	    public Collection<Visit> findVisitsByPetId(int petId) {
637	        return visitRepository.findByPetId(petId);
638	    }
639	
640	    @Override
641	    @Transactional(readOnly = true)
642	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
643	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
644	    }
645	
646	    private <T> T findEntityById(Supplier<T> supplier) {
647	        try {
648	            return supplier.get();
649	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
650	            // Just ignore not found exceptions for Jdbc/Jpa realization
651	            return null;
652	        }
653	    }
654	
655	}
